import{_ as a,o,c,a2 as i}from"./chunks/framework.Cdp8-jB6.js";const g=JSON.parse('{"title":"Archived one-shot scripts (scripts/_archive/)","description":"","frontmatter":{},"headers":[],"relativePath":"reference/tooling/archive.md","filePath":"reference/tooling/archive.md"}'),s={name:"reference/tooling/archive.md"};function t(r,e,d,n,l,h){return o(),c("div",null,[...e[0]||(e[0]=[i('<h1 id="archived-one-shot-scripts-scripts-archive" tabindex="-1">Archived one-shot scripts (<code>scripts/_archive/</code>) <a class="header-anchor" href="#archived-one-shot-scripts-scripts-archive" aria-label="Permalink to &quot;Archived one-shot scripts (`scripts/_archive/`)&quot;">​</a></h1><blockquote><p>Inventory of the 135 retired one-shot scripts moved out of <code>scripts/</code> on 2026-06-28. These ran <strong>once</strong> during a specific wave/slice/migration and are kept for historical reference only — they are <strong>not</strong> re-runnable as-is (their relative imports no longer resolve from the archive depth) and are excluded from ESLint, Prettier, and <code>tsconfig</code>. Nothing in the live tree imports them (verified by reference check before the move).</p></blockquote><p><strong>If you need the behaviour of one again, don&#39;t un-archive it</strong> — read it for the recipe, then write a fresh standing tool (or extend an existing one) under <code>scripts/</code>. The recurring patterns these encode now live in durable tools: translation → <code>scripts/wave23/</code> + the ADR-069 gate; image sourcing → the <a href="./image-pipeline">image pipeline</a>; data shape → the schema + <code>validate-data</code>.</p><h2 id="why-these-were-archived" tabindex="-1">Why these were archived <a class="header-anchor" href="#why-these-were-archived" aria-label="Permalink to &quot;Why these were archived&quot;">​</a></h2><p>The live <code>scripts/</code> directory had grown to ~260 files, ~165 of them one-shots, drowning the ~60 standing tools agents actually need. Separating them makes the durable surface legible (see the <a href="./README">tooling index</a>) and stops new agents from cargo-culting a dead per-batch script when a standing tool exists.</p><h2 id="groups" tabindex="-1">Groups <a class="header-anchor" href="#groups" aria-label="Permalink to &quot;Groups&quot;">​</a></h2><h3 id="archive-i18n-36-—-per-wave-translation-passes" tabindex="-1"><code>_archive/i18n/</code> (36) — per-wave translation passes <a class="header-anchor" href="#archive-i18n-36-—-per-wave-translation-passes" aria-label="Permalink to &quot;`_archive/i18n/` (36) — per-wave translation passes&quot;">​</a></h3><p>The historical translation toolchain: <code>translate-*.mjs</code> (per-surface: satellites, belts, science, iconic missions, orbit rulers, fly phases, launchers, shuttles, panel/chip labels, tides, v0.7 UI, …), <code>apply-slice-*-translations.mjs</code>, <code>seed-satellite-i18n.mjs</code>, <code>paraglide-add-keys.mjs</code>, <code>add-flat-patch-i18n.mjs</code>, <code>patch-tooltip-messages.mjs</code>, <code>wave-credits-keys.mjs</code>, <code>fill-moon-sites-locale-gaps.ts</code>. <strong>Superseded by</strong> <code>scripts/wave23/</code> (catalog → maps → apply) + the ADR-069 overlay-completeness gate in <code>validate-data</code>.</p><h3 id="archive-image-sourcing-39-—-per-batch-fetch-hand-source-passes" tabindex="-1"><code>_archive/image-sourcing/</code> (39) — per-batch fetch + hand-source passes <a class="header-anchor" href="#archive-image-sourcing-39-—-per-batch-fetch-hand-source-passes" aria-label="Permalink to &quot;`_archive/image-sourcing/` (39) — per-batch fetch + hand-source passes&quot;">​</a></h3><p><code>fetch-batch-2-*</code>, <code>fetch-broader-*</code>, <code>fetch-followup-*</code>, <code>fetch-phase3c-*</code>, <code>fetch-right-stuff-*</code>, <code>fetch-satellite-*</code>, <code>fetch-slice-*</code>, <code>fetch-spacecraft-*</code>, <code>fetch-tier-*</code>, <code>fetch-v2-practice-pass</code>, <code>fetch-via-agency-registry</code>, <code>fetch-zero-image-entities</code>, <code>fetch-iconic-better-heroes</code>, the <code>handsource-*</code> family (11 manual-sourcing passes), <code>hubble-pass</code>, <code>sun-replace</code>, <code>audit-fleet-weak-heroes</code>, <code>audit-image-source-order</code>. <strong>Superseded by</strong> the standing <a href="./image-pipeline">image pipeline</a>: <code>fetch-assets.ts</code> (agency-first, staging-by-default), <code>fill-gallery-gaps.ts</code>, <code>source-known-gaps.ts</code>, <code>fetch-fleet-sub-a-curation.ts</code>.</p><h3 id="archive-slices-19-—-the-slice-by-slice-imagery-curation-waves" tabindex="-1"><code>_archive/slices/</code> (19) — the slice-by-slice imagery curation waves <a class="header-anchor" href="#archive-slices-19-—-the-slice-by-slice-imagery-curation-waves" aria-label="Permalink to &quot;`_archive/slices/` (19) — the slice-by-slice imagery curation waves&quot;">​</a></h3><p><code>slice-a-*</code> (dryrun / vision-pass / salvage / review / cluster-report / apply / manual-source), <code>slice-b-*</code>, <code>slice-explore-*</code>, <code>slice-f-audit</code>, <code>slice-pre-a-corpus-vet</code>, <code>build-slice-{a,b,c}-*</code>. The <code>/dev/slice-a-review</code> route is the (now-orphaned) review surface these fed; the durable equivalent is <code>/dev/staging</code> (RFC-029).</p><h3 id="archive-data-builds-20-—-one-time-catalog-builders" tabindex="-1"><code>_archive/data-builds/</code> (20) — one-time catalog builders <a class="header-anchor" href="#archive-data-builds-20-—-one-time-catalog-builders" aria-label="Permalink to &quot;`_archive/data-builds/` (20) — one-time catalog builders&quot;">​</a></h3><p><code>build-apollo-missions</code>, <code>build-mercury-missions</code>, <code>build-tier-{b,c,d,f,g}-*</code>, <code>build-followup-entries</code>, <code>build-right-stuff-entries</code>, <code>bodies-{apply,salvage}</code>, <code>belts-{curate,structure-curate}</code>, <code>copy-mission-to-fleet</code>, <code>curate-science-sections</code>, <code>augment-flight-rosters{,-2}</code>, <code>scaffold-fleet-entries</code>, <code>wire-spacecraft-refs</code>, <code>fix-stringified-arrays</code>. These seeded <code>static/data/</code> catalogs that are now committed and edited in place.</p><h3 id="archive-migrations-fixups-17-—-one-time-schema-migrations-backfills" tabindex="-1"><code>_archive/migrations-fixups/</code> (17) — one-time schema migrations + backfills <a class="header-anchor" href="#archive-migrations-fixups-17-—-one-time-schema-migrations-backfills" aria-label="Permalink to &quot;`_archive/migrations-fixups/` (17) — one-time schema migrations + backfills&quot;">​</a></h3><p><code>migrate-fleet-{crew-flights,en-us-overlays,learn-links}</code>, <code>migrate-{mission,site}-fleet-refs</code>, <code>backfill-{cislunar-profiles,region-bounds,traverse-stops,sidecar-from-report,walker-fallback-titles,crewed-flag}</code>, <code>remap-sidecars-after-dupe-delete</code>, <code>harvest-sidecars-from-sourcing-report</code>, <code>fill-{hotspot-metadata,site-story}-stubs</code>, <code>seed-iss-overlays</code>, <code>patch-image-provenance</code>. <strong>Note:</strong> <code>migrate-fleet-linked-missions.ts</code> and <code>migrate-fleet-linked-sites.ts</code> were <strong>kept</strong> in <code>scripts/</code> (not archived) because <code>validate-data</code> emits them as live fix-hints when <code>fleet_refs</code>↔<code>linked_*</code> drift — see <a href="./content-pipelines">content-pipelines.md</a>.</p><h3 id="archive-diagnostics-4-—-scratch-diagnostic-probes" tabindex="-1"><code>_archive/diagnostics/</code> (4) — scratch/diagnostic probes <a class="header-anchor" href="#archive-diagnostics-4-—-scratch-diagnostic-probes" aria-label="Permalink to &quot;`_archive/diagnostics/` (4) — scratch/diagnostic probes&quot;">​</a></h3><p><code>_hirise-{diag,dtype,pattern}.ts</code> (HiRISE format probes from the hotspots bring-up), <code>analyze-moon-meet-points.mjs</code>.</p><h2 id="reversibility" tabindex="-1">Reversibility <a class="header-anchor" href="#reversibility" aria-label="Permalink to &quot;Reversibility&quot;">​</a></h2><p>The move was <code>git mv</code> (history preserved). To inspect any script&#39;s full history: <code>git log --follow scripts/_archive/&lt;group&gt;/&lt;name&gt;</code>. Deleting <code>_archive/</code> entirely is safe at any time — nothing references it.</p>',20)])])}const f=a(s,[["render",t]]);export{g as __pageData,f as default};
